CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE auth_limits (key TEXT PRIMARY KEY, hits INTEGER NOT NULL, resets_at INTEGER NOT NULL);
CREATE TABLE restaurants (id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, cuisine TEXT NOT NULL, description TEXT NOT NULL, image TEXT NOT NULL, eta_min INTEGER NOT NULL, delivery_fee INTEGER NOT NULL CHECK(delivery_fee>=0), min_order INTEGER NOT NULL CHECK(min_order>=0), is_open INTEGER NOT NULL DEFAULT 1 CHECK(is_open IN(0,1)), tag TEXT NOT NULL DEFAULT '', featured INTEGER NOT NULL DEFAULT 0);
CREATE TABLE menu_items (id INTEGER PRIMARY KEY, restaurant_id INTEGER NOT NULL REFERENCES restaurants(id), name TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>0), image TEXT NOT NULL, is_veg INTEGER NOT NULL CHECK(is_veg IN (0,1)), available INTEGER NOT NULL DEFAULT 1 CHECK(available IN (0,1)), popular INTEGER NOT NULL DEFAULT 0);
CREATE INDEX menu_restaurant ON menu_items(restaurant_id);
CREATE TABLE favorites (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, restaurant_id INTEGER NOT NULL REFERENCES restaurants(id), PRIMARY KEY (user_id,restaurant_id));
CREATE TABLE addresses (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, label TEXT NOT NULL, recipient TEXT NOT NULL, phone TEXT NOT NULL, line1 TEXT NOT NULL, city TEXT NOT NULL, postal_code TEXT NOT NULL, is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN(0,1)));
CREATE INDEX addresses_owner ON addresses(user_id);
CREATE UNIQUE INDEX address_default ON addresses(user_id) WHERE is_default=1;
CREATE TABLE cart_items (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_id INTEGER NOT NULL REFERENCES menu_items(id), quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20), PRIMARY KEY(user_id,item_id));
CREATE TABLE coupons (code TEXT PRIMARY KEY, percent INTEGER NOT NULL CHECK(percent BETWEEN 1 AND 100), max_discount INTEGER NOT NULL, min_subtotal INTEGER NOT NULL, first_order_only INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, description TEXT NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), restaurant_id INTEGER NOT NULL REFERENCES restaurants(id), status TEXT NOT NULL CHECK(status IN('placed','confirmed','preparing','out_for_delivery','delivered','cancelled')), subtotal INTEGER NOT NULL, discount INTEGER NOT NULL, delivery_fee INTEGER NOT NULL, total INTEGER NOT NULL, coupon_code TEXT REFERENCES coupons(code), address_json TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', payment_method TEXT NOT NULL CHECK(payment_method='cod'), payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','collected','cancelled')), idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(user_id,idempotency_key));
CREATE INDEX orders_owner ON orders(user_id,created_at);
CREATE INDEX orders_status ON orders(status,created_at);
CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), item_id INTEGER NOT NULL REFERENCES menu_items(id), name TEXT NOT NULL, price INTEGER NOT NULL, quantity INTEGER NOT NULL);
CREATE TABLE order_events (id INTEGER PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), status TEXT NOT NULL, actor_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE reviews (id INTEGER PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), user_id INTEGER NOT NULL REFERENCES users(id), restaurant_id INTEGER NOT NULL REFERENCES restaurants(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX reviews_restaurant ON reviews(restaurant_id);
CREATE TABLE admin_audit (id INTEGER PRIMARY KEY, actor_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
